# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def heightOfTree(self, root: Optional[TreeNode]) -> int:
        def dfs(node):
            if node is None:
                return -1                 # height of an empty subtree
            # A real leaf b_i has left child b_{i-1} whose right child is b_i again
            if node.left is not None and node.left.right is node:
                return 0                  # leaf: stop, don't follow the cycle
            return 1 + max(dfs(node.left), dfs(node.right))

        return dfs(root)
